// 日本の一般的な食品300品 栄養値辞書
// 日本食品標準成分表（八訂）を参考にした可食部100gあたりの概算値
// ============================================================

const ZERO_NUTRIENTS = {
  calories: 0, protein: 0, fat: 0, carbs: 0, fiber: 0,
  vitA: 0, vitD: 0, vitE: 0, vitK: 0, vitB1: 0, vitB2: 0,
  vitB3: 0, vitB5: 0, vitB6: 0, vitB7: 0, vitB9: 0, vitB12: 0, vitC: 0,
  ca: 0, p: 0, mg: 0, na: 0, k: 0, fe: 0, zn: 0, cu: 0, mn: 0,
  iodine: 0, se: 0, mo: 0,
  ile: 0, leu: 0, lys: 0, met: 0, phe: 0, thr: 0, trp: 0, val: 0
};

function n(calories, protein, fat, carbs, fiber, extra = {}) {
  return {calories, protein, fat, carbs, fiber, ...extra};
}

function aminoFromProtein(protein) {
  if ((Number(protein) || 0) < 8) return {};
  return {
    ile: Math.round(protein * 45),
    leu: Math.round(protein * 80),
    lys: Math.round(protein * 70),
    met: Math.round(protein * 25),
    phe: Math.round(protein * 45),
    thr: Math.round(protein * 40),
    trp: Math.round(protein * 11),
    val: Math.round(protein * 50)
  };
}

function food(id, names, category, defaultGrams, per100g) {
  return {
    id,
    names,
    category,
    defaultGrams,
    per100g: {...ZERO_NUTRIENTS, ...aminoFromProtein(per100g.protein), ...per100g}
  };
}

